import{_ as e,o as n,c as t,a0 as i}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /surfaces","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/surfaces.md","filePath":"references/skills/surfaces.md"}'),o={name:"references/skills/surfaces.md"};function c(s,a,l,r,u,h){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="skill-surfaces" tabindex="-1">Skill: <code>/surfaces</code> <a class="header-anchor" href="#skill-surfaces" aria-label="Permalink to &quot;Skill: `/surfaces`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>surfaces</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/surfaces &lt;Tên Surface&gt;</code> (Ví dụ: <code>/surfaces &quot;Admin Portal&quot;</code>)</li><li>Có thể dùng kèm với <code>common</code>: <code>/surfaces common</code> (cho toàn hệ thống) hoặc <code>/surfaces &quot;Admin Portal&quot; common</code> (Share riêng trong phạm vi 1 Surface).</li><li>Có thể kết hợp cờ khảo cổ mã nguồn cũ: <code>/legacy /surfaces</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Tên Business Surface (VD: Customer App, Admin Portal, Integration Gateway).</li><li>Nếu có <code>/legacy</code>: Đọc <code>legacy-repos.local.json</code>.</li><li>Định danh và thông tin về người dùng (actors), kênh tương tác (channels) và phạm vi nghiệp vụ (business responsibility).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Khởi tạo thư mục và sinh ra các file tài liệu Markdown lưu tại <code>surfaces/&lt;Tên Surface&gt;/</code>.</li><li>Nếu có cờ <code>/legacy</code>: Khảo cổ mã nguồn cũ và map lại thành <code>legacy-surface.md</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Dùng để thiết kế tầng <strong>Giao diện Nghiệp vụ (Business Surfaces)</strong>. Tầng này định nghĩa rõ &quot;Ai (Actor) - làm gì (Business Responsibility) - trên kênh nào (Channel)&quot;.</li><li>Ranh giới Kỹ thuật (Surface Technical Boundary): <ul><li>Thư mục Surface <strong>CHỈ ĐƯỢC PHÉP</strong> chứa tài liệu kỹ thuật liên quan đến UI/Page Building (UI Layout, States, Props) hoặc Data Schema của 1 API đơn lẻ.</li><li><strong>TUYỆT ĐỐI CẤM</strong> nhét cấu trúc Backend server, Load balancer, cấu trúc Database ngầm vào đây.</li><li>Luồng xuyên suốt (Cross-flows) trong thư mục Surface chỉ được phép là luồng điều hướng màn hình (User navigation journeys), CẤM chứa luồng kỹ thuật Backend chéo.</li></ul></li><li>Lưu ý: <strong>API NỘI BỘ KHÔNG PHẢI LÀ MỘT SURFACE</strong>. Đừng bao giờ tạo thư mục <code>surfaces/API</code> để chứa API của một màn hình. Tuy nhiên, ngoại lệ duy nhất là các <strong>API giao tiếp ngoại vi</strong> (Webhook, Open API cho bên thứ 3) thì được xem là một kênh giao tiếp độc lập và nằm trong Surface tích hợp (thường đặt tại <code>surfaces/integrations/</code>).</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Được kích hoạt/điều phối bởi <code>/architecture</code>.</li><li>Nếu thiết kế chung cho toàn hệ thống → Gọi <code>/common</code>.</li><li>Đi sâu vào thiết kế chức năng bên trong Surface → Gọi <code>/module</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/surfaces</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=e(o,[["render",c]]);export{g as __pageData,p as default};
